// Engine A -- merge sort. No preprocessing, cache-friendly, best constants.
long long mergeCount(vector<int>& a, vector<int>& buf, int lo, int hi) {
    if (hi - lo < 2) return 0;
    int mid = lo + (hi - lo) / 2;
    long long inv = mergeCount(a, buf, lo, mid) + mergeCount(a, buf, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) buf[k++] = a[i++];
        else { inv += mid - i; buf[k++] = a[j++]; }
    }
    while (i < mid) buf[k++] = a[i++];
    while (j < hi)  buf[k++] = a[j++];
    copy(buf.begin() + lo, buf.begin() + hi, a.begin() + lo);
    return inv;
}

// Engine B -- Fenwick over compressed ranks. Wins when the value range is small.
long long inversionsFenwick(const vector<int>& a) {
    vector<int> sorted_(a);
    sort(sorted_.begin(), sorted_.end());
    sorted_.erase(unique(sorted_.begin(), sorted_.end()), sorted_.end());
    int m = (int)sorted_.size();
    vector<int> bit(m + 1, 0);
    auto add = [&](int i) { for (; i <= m; i += i & -i) ++bit[i]; };
    auto qry = [&](int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };

    long long inv = 0;
    for (int seen = 0; seen < (int)a.size(); ++seen) {
        int r = (int)(lower_bound(sorted_.begin(), sorted_.end(), a[seen]) - sorted_.begin()) + 1;
        inv += seen - qry(r);      // inserted already and strictly greater
        add(r);
    }
    return inv;
}

