def inversions_merge(a: list[int]) -> int:
    """Engine A -- merge sort. No preprocessing, best constants."""
    def rec(arr):
        if len(arr) < 2:
            return arr, 0
        mid = len(arr) // 2
        left, il = rec(arr[:mid])
        right, ir = rec(arr[mid:])
        out, inv = [], il + ir
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                out.append(left[i]); i += 1
            else:
                inv += len(left) - i
                out.append(right[j]); j += 1
        out += left[i:]
        out += right[j:]
        return out, inv
    return rec(a)[1]


def inversions_fenwick(a: list[int]) -> int:
    """Engine B -- Fenwick over compressed ranks."""
    if not a:
        return 0
    rank = {v: i + 1 for i, v in enumerate(sorted(set(a)))}
    m = len(rank)
    bit = [0] * (m + 1)

    def add(i):
        while i <= m:
            bit[i] += 1
            i += i & -i

    def qry(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    inv = 0
    for seen, v in enumerate(a):
        r = rank[v]
        inv += seen - qry(r)      # inserted already and strictly greater
        add(r)
    return inv

