vector<uint32_t> radixSort(vector<uint32_t> a) {
    const int BITS = 16, BUCKETS = 1 << BITS, MASK = BUCKETS - 1;
    vector<uint32_t> tmp(a.size());          // one scratch buffer, reused
    for (int shift = 0; shift < 32; shift += BITS) {
        vector<size_t> count(BUCKETS + 1, 0);
        for (uint32_t x : a) ++count[((x >> shift) & MASK) + 1];
        for (int b = 0; b < BUCKETS; ++b) count[b + 1] += count[b];   // prefix sums
        for (uint32_t x : a) tmp[count[(x >> shift) & MASK]++] = x;   // STABLE scatter
        a.swap(tmp);
    }
    return a;
}

vector<int> countSmaller(const vector<int>& a) {
    int n = (int)a.size();
    vector<int> sorted_(a);
    sort(sorted_.begin(), sorted_.end());
    sorted_.erase(unique(sorted_.begin(), sorted_.end()), sorted_.end());
    int m = (int)sorted_.size();
    vector<int> bit(m + 1, 0);
    auto add = [&](int i) { for (; i <= m; i += i & -i) ++bit[i]; };
    auto qry = [&](int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };

    vector<int> out(n);
    for (int i = n - 1; i >= 0; --i) {        // right to left
        int r = (int)(lower_bound(sorted_.begin(), sorted_.end(), a[i]) - sorted_.begin()) + 1;
        out[i] = qry(r - 1);                  // already-seen values STRICTLY smaller
        add(r);                               // insert AFTER querying
    }
    return out;
}

