    if n == 0:
        return []
    rank = {v: i + 1 for i, v in enumerate(sorted(set(a)))}
    m = len(rank)
    bit = [0] * (m + 1)

    def add(i):
        while i <= m:
            bit[i] += 1
            i += i & -i

    def qry(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

