int reversePairsRec(vector<int>& a, vector<int>& buf, int lo, int hi) {
    if (hi - lo < 2) return 0;
    int mid = lo + (hi - lo) / 2;
    int count = reversePairsRec(a, buf, lo, mid) + reversePairsRec(a, buf, mid, hi);

    // Both halves are sorted. Count pairs BEFORE merging: the condition
    // a[i] > 2*a[j] does not line up with the merge's own comparison.
    int j = mid;
    for (int i = lo; i < mid; ++i) {
        while (j < hi && (long long)a[i] > 2LL * a[j]) ++j;   // 2LL: overflow guard
        count += j - mid;
    }

    int i = lo; j = mid; int k = lo;
    while (i < mid && j < hi) buf[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
    while (i < mid) buf[k++] = a[i++];
    while (j < hi)  buf[k++] = a[j++];
    copy(buf.begin() + lo, buf.begin() + hi, a.begin() + lo);
    return count;
}
int reversePairs(vector<int> a) {
    vector<int> buf(a.size());
    return reversePairsRec(a, buf, 0, (int)a.size());
}

