def reverse_pairs(a: list[int]) -> int:
    a = a[:]
    buf = [0] * len(a)

    def rec(lo, hi):
        if hi - lo < 2:
            return 0
        mid = lo + (hi - lo) // 2
        count = rec(lo, mid) + rec(mid, hi)

        # Both halves are sorted. Count pairs BEFORE merging: the condition
        # a[i] > 2*a[j] does not line up with the merge's own comparison.
        j = mid
        for i in range(lo, mid):
            while j < hi and a[i] > 2 * a[j]:
                j += 1
            count += j - mid

        i, j, k = lo, mid, lo
        while i < mid and j < hi:
            if a[i] <= a[j]:
                buf[k] = a[i]; i += 1
            else:
                buf[k] = a[j]; j += 1
            k += 1
        while i < mid:
            buf[k] = a[i]; i += 1; k += 1
        while j < hi:
            buf[k] = a[j]; j += 1; k += 1
        a[lo:hi] = buf[lo:hi]
        return count

    return rec(0, len(a))

