struct Task { int priority, cost, id; };

// priority DESC, then cost ASC, then id ASC. Every key is compared strictly;
// the chain falls through only when keys are EQUAL.
bool taskLess(const Task& a, const Task& b) {
    if (a.priority != b.priority) return a.priority > b.priority;   // DESC
    if (a.cost != b.cost)         return a.cost < b.cost;           // ASC
    return a.id < b.id;                                             // ASC, strict
}

vector<Task> sortTasks(vector<Task> v) {
    sort(v.begin(), v.end(), taskLess);
    return v;
}

