def sort_tasks(tasks: list[tuple]) -> list[tuple]:
    """tasks are (priority, cost, id) -> priority DESC, cost ASC, id ASC.

    Negating the descending key keeps every comparison strict, which is the
    Python equivalent of never writing <= in a C++ comparator."""
    return sorted(tasks, key=lambda t: (-t[0], t[1], t[2]))


def task_less(a: tuple, b: tuple) -> bool:
    """The explicit tie-chain, for comparing against the key-based version."""
    if a[0] != b[0]:
        return a[0] > b[0]        # DESC
    if a[1] != b[1]:
        return a[1] < b[1]        # ASC
    return a[2] < b[2]            # ASC, strict

