int smallestDistancePair(vector<int> a, int k) {
    sort(a.begin(), a.end());
    int n = (int)a.size();

    // pairs with distance <= d, counted by a two-pointer sweep in O(n)
    auto countAtMost = [&](int d) {
        int total = 0, lo = 0;
        for (int hi = 0; hi < n; ++hi) {
            while (a[hi] - a[lo] > d) ++lo;
            total += hi - lo;              // all pairs ending at hi
        }
        return total;
    };

    int lo = 0, hi = a[n - 1] - a[0];
    while (lo < hi) {                      // find the SMALLEST d with count >= k
        int mid = lo + (hi - lo) / 2;
        if (countAtMost(mid) >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

