def smallest_distance_pair(a: list[int], k: int) -> int:
    a = sorted(a)
    n = len(a)

    def count_at_most(d):
        """Pairs with distance <= d, via a two-pointer sweep in O(n)."""
        total = lo = 0
        for hi in range(n):
            while a[hi] - a[lo] > d:
                lo += 1
            total += hi - lo          # all pairs ending at hi
        return total

    lo, hi = 0, a[-1] - a[0]
    while lo < hi:                    # find the SMALLEST d with count >= k
        mid = (lo + hi) // 2
        if count_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
